// Prompt: "Adopt and discard in the editor"
// Changes: What the adopt dialog offers, from the changes module's per-part flags: unchanged parts cannot be ticked,
//          parts changed on both sides start unticked (with a warning), the others start ticked; adopting the
//          definition without the grammar rules (or the other way round) warns. Pure, no DOM.

import type { DraftChanges } from './changes'
import { PARTS, type PartName } from './parts'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: A part counts as changed in the draft when the draft differs from its base (not from the current
//          project): a part changed only in the project is shown as unchanged in the draft and cannot be ticked,
//          so adopting never silently reverts newer project work.
export interface AdoptChoice {
  /** The draft changed this part (and it differs from the project), so it can be adopted. */
  selectable: boolean
  /** The project changed this part too since the draft was forked (adopting it overwrites that change). */
  bothSides: boolean
  /** Only the project changed this part since the draft was forked; the draft's part is its old base. */
  projectOnly: boolean
}

export type AdoptChoices = Record<PartName, AdoptChoice>

export const adoptChoices = (changes: Pick<DraftChanges, PartName>): AdoptChoices =>
  Object.fromEntries(
    PARTS.map((part) => {
      const flags = changes[part]
      // Without a base, "differs from the project" is all we know.
      const inDraft = flags.changedInDraft ?? true
      const selectable = flags.changed && inDraft
      return [part, { selectable, bothSides: selectable && flags.changedOnBothSides === true, projectOnly: flags.changed && !inDraft }]
    }),
  ) as AdoptChoices

/** The parts ticked when the dialog opens. */
export const initialSelection = (choices: AdoptChoices): PartName[] => PARTS.filter((part) => choices[part].selectable && !choices[part].bothSides)

/** The warning for adopting only one of the definition and the grammar rules while the draft changes both; else null. */
export function pairingWarning(choices: AdoptChoices, selected: readonly PartName[]): string | null {
  const both = choices.definition.selectable && choices.grammarRules.selectable
  if (!both) return null
  const def = selected.includes('definition')
  const rules = selected.includes('grammarRules')
  if (def && !rules) return 'Definíciu bez gramatických pravidiel: pravidlá projektu nemusia sedieť s novými symbolmi.'
  if (rules && !def) return 'Gramatické pravidlá bez definície: nové pravidlá môžu používať symboly, ktoré projekt nedefinuje.'
  return null
}
